import { describe, expect, it } from 'vitest';
import { RateLimiter } from '../src/lib/limiter';
import { setup } from './helpers';

describe('POST /webhooks rate limiting', () => {
  it('answers 429 with a Retry-After header when a tenant exceeds the limit', async () => {
    const { postWebhook } = setup({ rateLimitMax: 2, rateLimitWindowMs: 60000 });
    expect((await postWebhook('tenant-a', { type: 'one' })).status).toBe(202);
    expect((await postWebhook('tenant-a', { type: 'two' })).status).toBe(202);

    const limited = await postWebhook('tenant-a', { type: 'three' });
    expect(limited.status).toBe(429);
    expect(limited.headers.get('Retry-After')).toMatch(/^\d+$/);
    expect(await limited.json()).toMatchObject({ error: 'rate limit exceeded' });
  });

  it('does not rate-limit other tenants', async () => {
    const { postWebhook } = setup({ rateLimitMax: 1, rateLimitWindowMs: 60000 });
    expect((await postWebhook('tenant-a', { type: 'one' })).status).toBe(202);
    expect((await postWebhook('tenant-a', { type: 'two' })).status).toBe(429);
    expect((await postWebhook('tenant-b', { type: 'one' })).status).toBe(202);
  });

  it('reads the limit from config', async () => {
    const { postWebhook } = setup({ rateLimitMax: 3, rateLimitWindowMs: 60000 });
    for (let i = 0; i < 3; i += 1) {
      expect((await postWebhook('tenant-a', { type: `t${i}` })).status).toBe(202);
    }
    expect((await postWebhook('tenant-a', { type: 'over' })).status).toBe(429);
  });
});

describe('RateLimiter', () => {
  it('opens a new window after the configured window elapses', () => {
    const limiter = new RateLimiter();
    expect(limiter.check('tenant-a', 1, 1000, 0).allowed).toBe(true);
    expect(limiter.check('tenant-a', 1, 1000, 500).allowed).toBe(false);
    expect(limiter.check('tenant-a', 1, 1000, 1000).allowed).toBe(true);
  });
});
